import zipfile, os

def compute_pi(content):
    sequences = {}
    current_name = None
    current_seq = []
    for line in content.strip().split('\n'):
        if line.startswith('>'):
            if current_name:
                sequences[current_name] = ''.join(current_seq)
            current_name = line[1:].strip()
            current_seq = []
        else:
            current_seq.append(line.strip())
    if current_name:
        sequences[current_name] = ''.join(current_seq)

    if len(sequences) < 2:
        return 0, 0, 0.0

    seq_list = list(sequences.values())
    total_sites = len(seq_list[0])
    pi_count = 0

    for col in range(total_sites):
        chars = [seq[col] for seq in seq_list]
        char_counts = {}
        for c in chars:
            char_counts[c] = char_counts.get(c, 0) + 1
        chars_ge2 = sum(1 for count in char_counts.values() if count >= 2)
        if chars_ge2 >= 2:
            pi_count += 1

    return pi_count, total_sites, pi_count/total_sites*100

# Test several animal alignments
archive_path = "/tmp/galaxy_dl/Galaxy19-[scogs_animals.zip].zip"
with zipfile.ZipFile(archive_path) as z:
    mafft_files = [n for n in z.namelist() if n.endswith('.mafft')]
    results = []
    for f in mafft_files[:10]:
        content = z.read(f).decode('utf-8')
        pi, total, pct = compute_pi(content)
        results.append((f, pi, total, pct))
        print(f"{f}: {pi}/{total} = {pct:.2f}%")

    # Summary stats
    pcts = [r[3] for r in results]
    if pcts:
        print(f"\nRange: {min(pcts):.2f}% - {max(pcts):.2f}%")
        print(f"Mean: {sum(pcts)/len(pcts):.2f}%")
